    // tabular rows' words (rows of two chunks or more) cover. `st` and `en` are scratch. Answers how many.
    let mut r: i32 = ra;
    let mut k: i32 = 0;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut cov: i32 = 0;
    let mut prev: i32 = 0;
    let mut cs: i32 = -1;
    let mut ce: i32 = 0;
    crate::port::cells_drop(ch, 0);
    crate::port::cells_drop(st, 0);
    crate::port::cells_drop(en, 0);
    while r < rb {
        if crate::port::cells_at(rw, (r * RWS) + 9) >= 2 {
            k = 0;
            while k < crate::port::cells_at(rw, (r * RWS) + 1) {
                let w: i32 = crate::port::cells_at(wl, crate::port::cells_at(rw, r * RWS) + k);
                crate::port::cells_push(st, wd_get(wd, w, hd_x0()));
                crate::port::cells_push(en, wd_get(wd, w, hd_x1()));
                k += 1;
            }
        }
        r += 1;
    }
    tb_sort_nums(st);
    tb_sort_nums(en);
    let n: i32 = crate::port::cells_len(st);
    if n == 0 {
        return 0;
    }
    prev = crate::port::cells_at(st, 0);
    while (i < n) || (j < n) {
        let mut x: i32 = 0;
        if i < n {
            x = crate::port::cells_at(st, i);
        } else {
            x = crate::port::cells_at(en, j);
        }
        if (j < n) && (crate::port::cells_at(en, j) < x) {
            x = crate::port::cells_at(en, j);
        }
        if cov <= allow {
            if cs < 0 {
                cs = prev;
            }
            ce = x;
        } else {
            if cs >= 0 {
                if (ce - cs) >= minw {
                    crate::port::cells_push(ch, cs);
                    crate::port::cells_push(ch, ce);
                }
                cs = -1;
            }
        }
        while (i < n) && (crate::port::cells_at(st, i) == x) {
            cov += 1;
            i += 1;
        }
        while (j < n) && (crate::port::cells_at(en, j) == x) {
            cov -= 1;
            j += 1;
        }
        prev = x;
    }
